def rebuild(n):
    gi=G[f'Demo pair {n} input']; go=G[f'Demo pair {n} output']
    cs=comps(gi)
    ref=[c for c,s in cs if c==8][0]; tr=min(r for r,_ in [p for q,s in cs if q==ref for p in s])
    res=[[0]*len(gi[0]) for _ in range(len(gi))]
    for c,s in cs:
        t=min(r for r,_ in s); sh=tr-t
        for (r,cc) in s:
            rr=r+sh; res[rr][cc]=c
    return gi,go,res
