def load():
    import os,re,json as _j
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps(g):
    H=len(g);W=len(g[0]);seen=set();out=[]
    for i in range(H):
        for j in range(W):
            c=g[i][j]
            if (i,j) in seen or c==0:continue
            st={(i,j)};toadd=[(i,j)]
            while toadd:
                a,b=toadd.pop()
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+dx,b+dy
                    if 0<=x<H and 0<=y<W and (x,y) not in st and g[x][y]==c:
                        st.add((x,y));toadd.append((x,y))
            seen|=st;out.append((c,st))
    return out
def f(g):
    cs=comps(g)
    anchor=min(min(r for r,_ in s) for c,s in cs if c==8)
    res=[[0]*len(g[0]) for _ in range(len(g))]
    for c,s in cs:
        if c==8: continue
        top=min(r for r,_ in s); shift=anchor-top
        for (r,cc) in s:
            res[r+shift][cc]=c
    return res
